import{_ as n,C as r,o as s,c as l,j as d,a as e,E as o,ah as i}from"./chunks/framework.BpF7DVZ1.js";const m=JSON.parse('{"title":"澄清问卷","description":"","frontmatter":{},"headers":[],"relativePath":"components/question-flow.md","filePath":"components/question-flow.md","lastUpdated":1788635489000}'),u={name:"components/question-flow.md"},h={id:"澄清问卷",tabindex:"-1"};function p(g,t,f,b,w,x){const a=r("Badge"),c=r("XhDemo");return s(),l("div",null,[d("h1",h,[t[0]||(t[0]=e("澄清问卷 ",-1)),o(a,{type:"info",text:"question-flow"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#澄清问卷","aria-label":'Permalink to "澄清问卷 <Badge type="info" text="question-flow" />"'},"​",-1))]),t[3]||(t[3]=i('<p>动手之前先问几句：一次一题，人逐题作答，答完一起提交。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>需求还差几处没说清，把含糊的地方拆成几道选择题问回去。</li><li>一次要问的不止一件事，而每件都只要一两秒就能答完。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只问一件事：那是一个<a href="./radio-group">单选组</a>或<a href="./checkbox-group">复选框组</a>，不必套一层问卷。</li><li>要人批准一次危险动作：那是闸门，用<a href="./approval">审批</a>——它的出口只有批准与拒绝两条， 没有「跳过」，也没有「答完再说」。</li><li>要收一份长表单：字段之间有校验与联动，用<a href="./form">表单</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>一次只暴露一题</strong>：非当前题对读屏 <code>aria-hidden</code>、对键盘 <code>inert</code>，里面的可聚焦物另发 <code>tabindex=&quot;-1&quot;</code>。 它们仍留在轨道上，只是走不到——这样卡片高度才有得可量，来回翻页也不必重建 DOM。</li><li><strong>高度与位移是量出来的，不是猜的</strong>：机器在活 DOM 上量当前题的盒，把结果写进 context， 连接层只把它格式化成两个私有槽（视口高度与轨道位移）。连接层是渲染期纯函数， 不查 DOM、不起定时器、不读时钟。</li><li><strong>单选自动前进，多选等人点继续</strong>：选中一项后隔一小段自动翻到下一题；连着改主意时， 每改一次都从整段延时重新计。<strong>自动前进只走下一题</strong>——末题上它停住，不替人按发送。</li><li><strong>一颗按钮两个身份</strong>：不是末题时是「继续」，末题时是「发送」。它原位换 <code>data-mode</code> 与可访问名， 正在按它的人不会按空。</li><li><strong>自由文本与选项同等算数</strong>：写了一句「都不是，我想要……」就算答过了这一题，继续键随之亮起。</li><li>进度只播报一次：<code>counter</code> 那格 <code>aria-hidden</code>，逐题跳动的数字不进活区； 换题与交卷由 <code>announcement</code> 念一句。</li><li>跳过是明路：<code>allowSkip</code> 关掉时整颗跳过键收起，而不是留一颗按不动的按钮。 末题上跳过即交卷——否则最后一题没有出口，人会被困在那里。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一次一题：单选选中后自动翻到下一题，多选等人点继续，末题上那颗按钮变成发送</p>',10)),o(c,{src:"question-flow/01-basic"}),t[4]||(t[4]=d("h3",{id:"自由文本与跳过",tabindex:"-1"},[e("自由文本与跳过 "),d("a",{class:"header-anchor",href:"#自由文本与跳过","aria-label":'Permalink to "自由文本与跳过"'},"​")],-1)),t[5]||(t[5]=d("p",null,"选项之外还能自己写一句，写了就算答过；关掉自动前进，每题都等人点继续",-1)),o(c,{src:"question-flow/02-note"}),t[6]||(t[6]=d("h3",{id:"受控当前题",tabindex:"-1"},[e("受控当前题 "),d("a",{class:"header-anchor",href:"#受控当前题","aria-label":'Permalink to "受控当前题"'},"​")],-1)),t[7]||(t[7]=d("p",null,"进度归宿主管：外面的按钮直接跳题，答案也一并受控，组件只发意图",-1)),o(c,{src:"question-flow/03-controlled"}),t[8]||(t[8]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[9]||(t[9]=d("p",null,"size 换问句、选项行与页脚按钮的几何档，三档共用同一份问题",-1)),o(c,{src:"question-flow/04-size"}),t[10]||(t[10]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-question-flow&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhQuestionFlowCounter</code> <code>XhQuestionFlowFooter</code> <code>XhQuestionFlowGroup</code> <code>XhQuestionFlowItem</code> <code>XhQuestionFlowItemIndicator</code> <code>XhQuestionFlowItemText</code> <code>XhQuestionFlowLiveRegion</code> <code>XhQuestionFlowNextTrigger</code> <code>XhQuestionFlowNote</code> <code>XhQuestionFlowPrevTrigger</code> <code>XhQuestionFlowPrompt</code> <code>XhQuestionFlowQuestion</code> <code>XhQuestionFlowResult</code> <code>XhQuestionFlowRoot</code> <code>XhQuestionFlowSkipTrigger</code> <code>XhQuestionFlowSubmitTrigger</code> <code>XhQuestionFlowTrack</code> <code>XhQuestionFlowViewport</code></td></tr><tr><td>组合式函数</td><td><code>useQuestionFlow</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/question-flow.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;question-flow&quot;</code>：<strong><code>root</code></strong> · <code>viewport</code> · <strong><code>track</code></strong> · <strong><code>question</code></strong> · <code>prompt</code> · <code>group</code> · <code>item</code> · <code>item-indicator</code> · <code>item-text</code> · <code>note</code> · <code>footer</code> · <code>prev-trigger</code> · <code>counter</code> · <code>next-trigger</code> · <code>skip-trigger</code> · <strong><code>submit-trigger</code></strong> · <code>result</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>questions</code></td><td><code>readonly QuestionFlowQuestion[]</code></td><td></td><td></td></tr><tr><td><code>index</code></td><td><code>number</code></td><td></td><td>当前题下标。给定即受控：内部不再自改，只发 onIndexChange。</td></tr><tr><td><code>defaultIndex</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>answers</code></td><td><code>QuestionFlowAnswers</code></td><td></td><td>答案表。给定即受控。</td></tr><tr><td><code>defaultAnswers</code></td><td><code>QuestionFlowAnswers</code></td><td></td><td></td></tr><tr><td><code>notes</code></td><td><code>QuestionFlowNotes</code></td><td></td><td>自由文本表。给定即受控。</td></tr><tr><td><code>defaultNotes</code></td><td><code>QuestionFlowNotes</code></td><td></td><td></td></tr><tr><td><code>status</code></td><td><code>QuestionFlowStatus</code></td><td></td><td>答题状态。给定即受控。</td></tr><tr><td><code>defaultStatus</code></td><td><code>QuestionFlowStatus</code></td><td></td><td></td></tr><tr><td><code>autoAdvance</code></td><td><code>boolean</code></td><td></td><td>单选选中后自动走下一题，默认开。 <strong>它只走下一题，末题上不会替人按发送。</strong></td></tr><tr><td><code>autoAdvanceDelay</code></td><td><code>number</code></td><td></td><td>自动前进前等多久（毫秒），默认 480。非有限值或负数不起计时器。</td></tr><tr><td><code>allowSkip</code></td><td><code>boolean</code></td><td></td><td>允许跳过，默认开。关掉后跳过按钮收起，SKIP 事件也不再生效。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>选项组内漫游走到尽头是否回绕，默认 true。</td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;QuestionFlowTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onIndexChange</code></td><td><code>(details: QuestionFlowIndexChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onAnswersChange</code></td><td><code>(details: QuestionFlowAnswersChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onNotesChange</code></td><td><code>(details: QuestionFlowNotesChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onSkip</code></td><td><code>(details: QuestionFlowSkipDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onSubmit</code></td><td><code>(details: QuestionFlowSubmitDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>index-change</code></td><td><code>QuestionFlowIndexChangeDetails</code></td><td>当前题变化；detail 为 <code>{ index }</code></td></tr><tr><td><code>answers-change</code></td><td><code>QuestionFlowAnswersChangeDetails</code></td><td>答案变化；detail 为 <code>{ answers }</code></td></tr><tr><td><code>notes-change</code></td><td><code>QuestionFlowNotesChangeDetails</code></td><td>自由文本变化；detail 为 <code>{ notes }</code></td></tr><tr><td><code>skip</code></td><td><code>QuestionFlowSkipDetails</code></td><td>跳过一题；detail 为 <code>{ index, questionId }</code></td></tr><tr><td><code>submit</code></td><td><code>QuestionFlowSubmitDetails</code></td><td>交卷；detail 为 <code>{ answers, notes }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhQuestionFlowItem</code></td><td><code>default</code></td><td><code>QuestionFlowOptionSlotProps</code></td><td></td></tr><tr><td><code>XhQuestionFlowRoot</code></td><td><code>default</code></td><td><code>QuestionFlowRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>state.get()</td></tr><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-indicator</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>result</code></td><td>state.get()</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>事件</strong>：<code>OPTION.TOGGLE</code> · <code>NOTE.SET</code> · <code>GOTO</code> · <code>NEXT</code> · <code>PREV</code> · <code>SKIP</code> · <code>SUBMIT</code> · <code>VIEWPORT.MEASURE</code> · <code>after.autoAdvance</code> · <code>CONTROLLED.ANSWERING</code> · <code>CONTROLLED.SUBMITTED</code></p><p><strong>判据</strong>：<code>isStatusControlled</code> · <code>canToggle</code> · <code>canSkip</code> · <code>isFirstQuestion</code> · <code>isLastQuestion</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useQuestionFlow</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>QuestionFlowStatus</code></td><td></td></tr><tr><td><code>submitted</code></td><td><code>boolean</code></td><td>已经交卷了。</td></tr><tr><td><code>index</code></td><td><code>number</code></td><td>夹到题数范围内的当前题下标。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td>题数。</td></tr><tr><td><code>current</code></td><td><code>QuestionFlowQuestion | undefined</code></td><td>当前题；一道题都没有时为 undefined。</td></tr><tr><td><code>isFirst</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isLast</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>canAdvance</code></td><td><code>boolean</code></td><td>当前题答得能往下走了吗：选了选项、写了自由文本，或这题本就可跳过。</td></tr><tr><td><code>allowSkip</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>counter</code></td><td><code>string</code></td><td>给眼睛看的 N / M。它对读屏隐藏，进度由播报区念。</td></tr><tr><td><code>announcement</code></td><td><code>string</code></td><td>念给读屏的那一句：答题中念进度，交卷后念结果。</td></tr><tr><td><code>answers</code></td><td><code>QuestionFlowAnswers</code></td><td></td></tr><tr><td><code>notes</code></td><td><code>QuestionFlowNotes</code></td><td></td></tr><tr><td><code>answersOf</code></td><td><code>(questionId: string) =&gt; readonly string[]</code></td><td></td></tr><tr><td><code>noteOf</code></td><td><code>(questionId: string) =&gt; string</code></td><td></td></tr><tr><td><code>isOptionSelected</code></td><td><code>(questionId: string, value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isCurrent</code></td><td><code>(questionId: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>goTo</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>next</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>prev</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>skip</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>submit</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>toggleOption</code></td><td><code>(questionId: string, value: string) =&gt; void</code></td><td></td></tr><tr><td><code>setNote</code></td><td><code>(questionId: string, value: string) =&gt; void</code></td><td></td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>重量一遍当前题的几何。换题与题目增删都会自动重量，容器尺寸变化由尺寸观察器接住。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getQuestionProps</code></td><td><code>(props: QuestionFlowQuestionProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPromptProps</code></td><td><code>(props: QuestionFlowQuestionProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>(props: QuestionFlowQuestionProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: QuestionFlowItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: QuestionFlowItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: QuestionFlowItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getNoteProps</code></td><td><code>(props: QuestionFlowQuestionProps) =&gt; T[&#39;input&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCounterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getSkipTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getSubmitTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getResultProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>焦点在当前题的选项上</td><td>焦点移到下一个可停留选项（禁用项跳过、尽头按 loop 回绕）；单选时同时选中它</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>焦点在当前题的选项上</td><td>焦点移到上一个可停留选项；单选时同时选中它</td></tr><tr><td><code>Home</code></td><td>焦点在当前题的选项上</td><td>焦点移到首个可停留选项；单选时同时选中它</td></tr><tr><td><code>End</code></td><td>焦点在当前题的选项上</td><td>焦点移到末个可停留选项；单选时同时选中它</td></tr><tr><td><code>Space</code></td><td>焦点在当前题的选项上</td><td>切换该项。单选点已选中的那一项不取消</td></tr><tr><td><code>Enter</code></td><td>焦点在当前题的选项或自由文本上，且这一题答得能往下走</td><td>前进一题；已经在末题就交卷</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>question</code></td><td><code>aria-hidden</code></td><td>undefined | &#39;true&#39;</td></tr><tr><td><code>question</code></td><td><code>aria-label</code></td><td>undefined | translations?.prompt</td></tr><tr><td><code>question</code></td><td><code>aria-labelledby</code></td><td><code>prompt</code> 部件的 id | undefined</td></tr><tr><td><code>question</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>group</code></td><td><code>aria-label</code></td><td>undefined | translations?.options</td></tr><tr><td><code>group</code></td><td><code>aria-labelledby</code></td><td><code>prompt</code> 部件的 id | undefined</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;radiogroup&#39; | &#39;group&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39; | &#39;checkbox&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>note</code></td><td><code>aria-label</code></td><td>translations?.note</td></tr><tr><td><code>prev-trigger</code></td><td><code>aria-label</code></td><td>translations?.prev</td></tr><tr><td><code>counter</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>next-trigger</code></td><td><code>aria-label</code></td><td>translations?.next</td></tr><tr><td><code>skip-trigger</code></td><td><code>aria-label</code></td><td>translations?.skip</td></tr><tr><td><code>submit-trigger</code></td><td><code>aria-label</code></td><td>translations?.send | translations?.continue</td></tr><tr><td><code>result</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr></tbody></table><ul><li>每题是 <code>role=group</code>，题干是它的可访问名；题干缺席时退到 <code>translations.prompt</code>。</li><li>选项组按题型取 <code>role=radiogroup</code>（单选）或 <code>role=group</code>（多选），同样由题干命名； 选项各自是 <code>role=radio</code> 或 <code>role=checkbox</code> 并显式报 <code>aria-checked</code>。</li><li>选项组内是漫游焦点：整组只占一个 Tab 位，落在选中项上，一个都没选时落首个可停留项。</li><li>上一题 / 下一题只给按钮入口，不吃全局按键——那会和选项漫游抢同一批方向键。 这两颗通常只画一枚箭头，所以它们的可访问名<strong>总会发出去</strong>（<code>translations.prev</code> / <code>translations.next</code>， 缺省 <code>Previous question</code> / <code>Next question</code>）；跳过键一般带可见文字，<code>translations.skip</code> 不给就不产出 <code>aria-label</code>。</li><li>自由文本那一格取 <code>translations.note</code> 作可及名（缺省 <code>Other answer</code>）， 占位文字另走 <code>translations.notePlaceholder</code>。</li><li>备注框与选项组都挡输入法组合态：组合期间的 Enter 是在确认候选词，不前进。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/question-flow.css</code> 按部件选择：<code>[data-scope=&quot;question-flow&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>question</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>group</code></td><td><code>data-select-mode</code></td><td>&#39;single&#39; | &#39;multiple&#39;</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-select-mode</code></td><td>&#39;single&#39; | &#39;multiple&#39;</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>data-select-mode</code></td><td>&#39;single&#39; | &#39;multiple&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>item-text</code></td><td><code>data-value</code></td><td>item.value</td></tr><tr><td><code>submit-trigger</code></td><td><code>data-mode</code></td><td>&#39;send&#39; | &#39;continue&#39;</td></tr><tr><td><code>result</code></td><td><code>data-state</code></td><td>state.get()</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-question-flow-action-font-size</code> · <code>--xh-question-flow-action-font-weight</code> · <code>--xh-question-flow-action-gap</code> · <code>--xh-question-flow-action-h</code> · <code>--xh-question-flow-action-px</code> · <code>--xh-question-flow-action-radius</code> · <code>--xh-question-flow-bg</code> · <code>--xh-question-flow-border</code> · <code>--xh-question-flow-counter-fg</code> · <code>--xh-question-flow-counter-font-size</code> · <code>--xh-question-flow-dot-radius</code> · <code>--xh-question-flow-dot-size</code> · <code>--xh-question-flow-footer-gap</code> · <code>--xh-question-flow-gap</code> · <code>--xh-question-flow-group-gap</code> · <code>--xh-question-flow-icon-size</code> · <code>--xh-question-flow-indicator-bg</code> · <code>--xh-question-flow-indicator-bg-checked</code> · <code>--xh-question-flow-indicator-border</code> · <code>--xh-question-flow-indicator-border-checked</code> · <code>--xh-question-flow-indicator-fg</code> · <code>--xh-question-flow-indicator-icon-size</code> · <code>--xh-question-flow-indicator-radius</code> · <code>--xh-question-flow-indicator-radius-single</code> · <code>--xh-question-flow-indicator-size</code> · <code>--xh-question-flow-item-bg</code> · <code>--xh-question-flow-item-bg-hover</code> · <code>--xh-question-flow-item-fg</code> · <code>--xh-question-flow-item-fg-checked</code> · <code>--xh-question-flow-item-font-size</code> · <code>--xh-question-flow-item-gap</code> · <code>--xh-question-flow-item-px</code> · <code>--xh-question-flow-item-py</code> · <code>--xh-question-flow-item-radius</code> · <code>--xh-question-flow-note-bg</code> · <code>--xh-question-flow-note-border</code> · <code>--xh-question-flow-note-fg</code> · <code>--xh-question-flow-note-font-size</code> · <code>--xh-question-flow-note-px</code> · <code>--xh-question-flow-note-py</code> · <code>--xh-question-flow-note-radius</code> · <code>--xh-question-flow-padding</code> · <code>--xh-question-flow-placeholder-fg</code> · <code>--xh-question-flow-prompt-fg</code> · <code>--xh-question-flow-prompt-font-size</code> · <code>--xh-question-flow-prompt-font-weight</code> · <code>--xh-question-flow-question-gap</code> · <code>--xh-question-flow-radius</code> · <code>--xh-question-flow-result-bg</code> · <code>--xh-question-flow-result-fg</code> · <code>--xh-question-flow-result-font-size</code> · <code>--xh-question-flow-result-font-weight</code> · <code>--xh-question-flow-result-gap</code> · <code>--xh-question-flow-result-px</code> · <code>--xh-question-flow-result-py</code> · <code>--xh-question-flow-result-radius</code> · <code>--xh-question-flow-shadow</code> · <code>--xh-question-flow-skip-bg</code> · <code>--xh-question-flow-skip-bg-hover</code> · <code>--xh-question-flow-skip-fg</code> · <code>--xh-question-flow-skip-fg-hover</code> · <code>--xh-question-flow-step-bg</code> · <code>--xh-question-flow-step-bg-hover</code> · <code>--xh-question-flow-step-fg</code> · <code>--xh-question-flow-step-fg-hover</code> · <code>--xh-question-flow-step-padding</code> · <code>--xh-question-flow-step-radius</code> · <code>--xh-question-flow-step-size</code> · <code>--xh-question-flow-submit-bg</code> · <code>--xh-question-flow-submit-bg-active</code> · <code>--xh-question-flow-submit-bg-hover</code> · <code>--xh-question-flow-submit-bg-off</code> · <code>--xh-question-flow-submit-fg</code> · <code>--xh-question-flow-submit-shadow</code> · <code>--xh-question-flow-track-gap</code> · <code>--xh-question-flow-track-y</code> · <code>--xh-question-flow-viewport-h</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-question-flow-in</code> · <code>xh-question-flow-result-in</code> · <code>xh-rise-in</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>block-size</code> · <code>border-color</code> · <code>box-shadow</code> · <code>color</code> · <code>opacity</code> · <code>scale</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>步进计数器想做成里程表那样逐位滚动：把 <code>counter</code> 当容器， 数字交给<a href="./number-animation">数值动画</a>，判定权仍在本组件手里。</li><li>问卷收上来之后要接着执行危险动作：把<a href="./approval">审批</a>排在它后面，两件事分开—— 问卷收的是「怎么做」，闸门收的是「做不做」。</li><li>装进<a href="./dialog">对话框</a>时把 <code>initialFocus</code> 指到当前题的第一个选项上， 打开即可直接用方向键作答。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>题目控制在三到五道：这是「动手前问一句」，不是问卷调查。</li><li>单选题的选项写成互斥的完整答案，别让人靠自由文本补充关键信息。</li><li>提交之后卡片不会自己消失：<strong>宿主要在 <code>onSubmit</code> 里决定接下来做什么</strong>， 想让它留在原地就渲 <code>result</code> 那一格。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它承载不可逆的动作确认：问卷没有「拒绝」这条路，跳过与不答都会让流程继续往下走。</li><li>把 <code>counter</code> 的文字当播报：那一格对读屏隐藏，改它不会让任何人听见。</li><li>关掉自动前进的同时把继续键也藏了：那样单选题就再没有出口。</li></ul>',48))])}const P=n(u,[["render",p]]);export{m as __pageData,P as default};
